// harness/test_nra_derive.mjs — T14 (ST4): byte-parity of the texture worker's
// JS NRA derivation port against the Rust originals it replaces.
//
// THE CONTRACT UNDER TEST. scene3d/texture_worker.js ports
// crates/holtburger-dat/src/normal_gen.rs (`normal_from_luminance`,
// `roughness_from_luminance`, `ao_from_luminance`) — the derivation the RGBA8
// runtime path performs wasm-side today (SurfacePixels.normalPixels et al.,
// both call sites at strength 1.0). Pass-05 D-05.5's compressed-only design
// moves that derive into the worker; "same output" is only claimable if the
// port is byte-identical, so this suite compares against goldens generated by
// RUNNING THE RUST SOURCE ITSELF:
//
//   harness/fixtures/nra-golden.json — emitted by a rustc-compiled harness
//   that include!'s normal_gen.rs verbatim over deterministic fixtures
//   (checker/LCG-noise/ramp at sizes straddling the 64px Gaussian-pre-blur
//   threshold, strengths 1.0 and 2.0). The generator reproduces
//   normal_gen.rs's own pinned golden (golden_8x8_checkerboard: corner(0,0)
//   [80,80,216], center(3,3) [128,128,255], corner(7,7) [175,175,216]),
//   which is asserted below so the fixture file itself cannot silently rot.
//
// Run:  node harness/test_nra_derive.mjs        (exit 0/1)

import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import {
  normalFromLuminance,
  roughnessFromLuminance,
  aoFromLuminance,
  deriveNraPlane,
} from "../scene3d/texture_worker.js";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const GOLDEN = JSON.parse(readFileSync(path.join(HERE, "fixtures", "nra-golden.json"), "utf8"));

let passed = 0;
let failed = 0;
function check(name, ok, detail) {
  console.log(`  [${ok ? "OK" : "FAIL"}] ${name}${detail ? " — " + detail : ""}`);
  ok ? passed++ : failed++;
}

function b64ToBytes(s) {
  return new Uint8Array(Buffer.from(s, "base64"));
}

// ── the SAME deterministic fixtures the Rust generator builds ───────────────

function checker(w, h, a, b) {
  const out = new Uint8Array(w * h * 4);
  let o = 0;
  for (let y = 0; y < h; y += 1) {
    for (let x = 0; x < w; x += 1) {
      const c = (x + y) % 2 === 0 ? a : b;
      out[o++] = c[0];
      out[o++] = c[1];
      out[o++] = c[2];
      out[o++] = 0xff;
    }
  }
  return out;
}

function noise(w, h, seed) {
  let s = (seed | 1) >>> 0;
  const next = () => {
    s = (Math.imul(s, 1664525) + 1013904223) >>> 0;
    return (s >>> 24) & 0xff;
  };
  const out = new Uint8Array(w * h * 4);
  let o = 0;
  for (let i = 0; i < w * h; i += 1) {
    out[o++] = next();
    out[o++] = next();
    out[o++] = next();
    out[o++] = 0xff;
  }
  return out;
}

function ramp(w, h, span) {
  const out = new Uint8Array(w * h * 4);
  let o = 0;
  for (let y = 0; y < h; y += 1) {
    for (let x = 0; x < w; x += 1) {
      const denom = w > 1 ? w - 1 : 1;
      // Rust f32::round = half away from zero; positive values agree with
      // Math.round. Value construction mirrors the Rust `(x/denom*span)
      // .round() as u8`.
      const v = Math.round(Math.fround(Math.fround(x / denom) * span)) & 0xff;
      out[o++] = v;
      out[o++] = v;
      out[o++] = v;
      out[o++] = 0xff;
    }
  }
  return out;
}

const FIXTURES = {
  checker8: { rgba: checker(8, 8, [0, 0, 0], [255, 255, 255]), w: 8, h: 8 },
  noise16: { rgba: noise(16, 16, 3), w: 16, h: 16 },
  noise65: { rgba: noise(65, 65, 37), w: 65, h: 65 },
  ramp33: { rgba: ramp(33, 33, 200.0), w: 33, h: 33 },
  noise64at: { rgba: noise(64, 64, 23), w: 64, h: 64 },
};

function bytesEqual(a, b) {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i += 1) if (a[i] !== b[i]) return false;
  return true;
}

function firstDiff(a, b) {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i += 1) if (a[i] !== b[i]) return `@${i}: ${a[i]} vs ${b[i]}`;
  return a.length !== b.length ? `len ${a.length} vs ${b.length}` : "equal";
}

// ── PART 1: the fixture file reproduces normal_gen.rs's own pinned golden ──
console.log("PART 1 — fixture provenance (normal_gen.rs golden_8x8_checkerboard)");
{
  const g = b64ToBytes(GOLDEN["checker8@1"].normal);
  check("corner (0,0) is [80,80,216]", g[0] === 80 && g[1] === 80 && g[2] === 216, `${g[0]},${g[1]},${g[2]}`);
  const c = (3 * 8 + 3) * 3;
  check("center (3,3) is [128,128,255]", g[c] === 128 && g[c + 1] === 128 && g[c + 2] === 255);
  const k = (7 * 8 + 7) * 3;
  check("corner (7,7) is [175,175,216]", g[k] === 175 && g[k + 1] === 175 && g[k + 2] === 216);
}

// ── PART 2: byte-identity, every fixture × strength × map ──────────────────
console.log("PART 2 — JS port vs Rust goldens, byte-for-byte");
for (const [key, row] of Object.entries(GOLDEN)) {
  if (key === "comment") continue;
  const [label] = key.split("@");
  const fx = FIXTURES[label];
  if (!fx) {
    check(`${key}: fixture known`, false, `no JS fixture for ${label}`);
    continue;
  }
  const s = row.strength;
  const n = normalFromLuminance(fx.rgba, row.w, row.h, s);
  const r = roughnessFromLuminance(fx.rgba, row.w, row.h, s);
  const a = aoFromLuminance(fx.rgba, row.w, row.h, s);
  check(`${key} normal`, bytesEqual(n, b64ToBytes(row.normal)), firstDiff(n, b64ToBytes(row.normal)));
  check(`${key} roughness`, bytesEqual(r, b64ToBytes(row.roughness)), firstDiff(r, b64ToBytes(row.roughness)));
  check(`${key} ao`, bytesEqual(a, b64ToBytes(row.ao)), firstDiff(a, b64ToBytes(row.ao)));
}

// ── PART 3: behavioral contracts the Rust tests pin ────────────────────────
console.log("PART 3 — Rust behavioral contracts");
{
  const solid = new Uint8Array(128 * 128 * 4);
  for (let i = 0; i < 128 * 128; i += 1) {
    solid[i * 4] = 128;
    solid[i * 4 + 1] = 128;
    solid[i * 4 + 2] = 128;
    solid[i * 4 + 3] = 255;
  }
  const n = normalFromLuminance(solid, 128, 128, 1.0);
  let flat = n.length === 128 * 128 * 3;
  for (let i = 0; flat && i < 128 * 128; i += 1) {
    if (n[i * 3] !== 128 || n[i * 3 + 1] !== 128 || n[i * 3 + 2] !== 255) flat = false;
  }
  check("uniform input ⇒ flat normals (128,128,255)", flat);
  const r = roughnessFromLuminance(solid, 128, 128, 1.0);
  check("uniform input ⇒ all-zero roughness", r.every((b) => b === 0));
  const a = aoFromLuminance(solid, 128, 128, 1.0);
  check("uniform input ⇒ all-white AO", a.every((b) => b === 255));
  check("malformed input ⇒ empty normal", normalFromLuminance(new Uint8Array(8), 4, 4, 1.0).length === 0);
  check("zero dims ⇒ empty", normalFromLuminance(solid, 0, 128, 1.0).length === 0);
}

// ── PART 4: the packed plane (pass-05 S3 nra result) ───────────────────────
console.log("PART 4 — deriveNraPlane packing (R/G=normal XY, B=roughness, A=AO)");
{
  const fx = FIXTURES.checker8;
  const plane = deriveNraPlane(fx.rgba, 8, 8);
  const n = b64ToBytes(GOLDEN["checker8@1"].normal);
  const r = b64ToBytes(GOLDEN["checker8@1"].roughness);
  const a = b64ToBytes(GOLDEN["checker8@1"].ao);
  check("plane length is w*h*4", plane.length === 8 * 8 * 4);
  let ok = true;
  for (let i = 0; i < 64 && ok; i += 1) {
    if (
      plane[i * 4] !== n[i * 3] ||
      plane[i * 4 + 1] !== n[i * 3 + 1] ||
      plane[i * 4 + 2] !== r[i] ||
      plane[i * 4 + 3] !== a[i]
    )
      ok = false;
  }
  check("channels are the golden maps, interleaved", ok);
  check("malformed input ⇒ empty plane", deriveNraPlane(new Uint8Array(4), 4, 4).length === 0);
}

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed === 0 ? 0 : 1);
